/**
 * Azure Static Web Apps API — /api/predictions
 * GET  ?lang=ar|en&anonId=...  → returns current daily AI question + vote counts
 * POST {anonId, vote, lang}    → cast a vote, returns updated counts
 *
 * Questions are generated by OpenAI once per UTC day and cached in Blob Storage.
 * Container: predictions-data
 *   Blobs: current-ar.json, current-en.json
 */

const { AzureOpenAI }       = require('openai');
const { BlobServiceClient } = require('@azure/storage-blob');

const API_KEY   = process.env.AZURE_OPENAI_API_KEY;
const API_VERSION = process.env.AZURE_OPENAI_API_VERSION || '2024-04-01-preview';
const ENDPOINT  = process.env.AZURE_OPENAI_ENDPOINT;
const MODEL     = process.env.AZURE_OPENAI_DEPLOYMENT || 'gpt-5-mini';

const CONTAINER = 'predictions-data';

// ─── Blob helpers ──────────────────────────────────────────────────────────────
function getContainerClient() {
  const connStr = process.env.AZURE_STORAGE_CONNECTION_STRING;
  if (!connStr) return null;
  return BlobServiceClient.fromConnectionString(connStr).getContainerClient(CONTAINER);
}

async function readBlob(container, name) {
  const client   = container.getBlockBlobClient(name);
  const download = await client.download();
  const chunks   = [];
  for await (const chunk of download.readableStreamBody) chunks.push(chunk);
  return JSON.parse(Buffer.concat(chunks).toString());
}

async function writeBlob(container, name, data) {
  const client = container.getBlockBlobClient(name);
  const json   = JSON.stringify(data);
  await client.upload(json, Buffer.byteLength(json), {
    blobHTTPHeaders: { blobContentType: 'application/json' },
    overwrite: true,
  });
}

// ─── Daily period key (UTC date) ──────────────────────────────────────────────
function todayKey() {
  const d = new Date();
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
}

function tomorrowMidnightUTC() {
  const d = new Date();
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + 1)).toISOString();
}

// ─── AI question generator ─────────────────────────────────────────────────────
async function generateQuestion(language) {
  const openai = new AzureOpenAI({ endpoint: ENDPOINT, apiKey: API_KEY, apiVersion: API_VERSION, deployment: MODEL });

  const prompt =
    language === 'ar'
      ? `أنت محلل سياسي متخصص في الشرق الأوسط. اطرح سؤالاً تنبؤياً واحداً بصيغة نعم/لا حول حدث سياسي قائم أو متوقع في المنطقة خلال الأيام القادمة.
أجب بـ JSON فقط (بدون markdown) بالصيغة التالية:
{"question":"السؤال","aiPick":"نعم أو لا","aiReason":"جملة واحدة تشرح التوقع"}`
      : `You are a political analyst specializing in the Middle East. Pose one predictive yes/no question about an ongoing or expected political event in the region within the next few days.
Respond with JSON only (no markdown):
{"question":"The question","aiPick":"Yes or No","aiReason":"One sentence explaining the prediction"}`;

  const completion = await openai.chat.completions.create({
    model: MODEL,
    messages: [{ role: 'user', content: prompt }],
    max_tokens: 300,
    temperature: 0.85,
  });

  const generated = JSON.parse(completion.choices[0].message.content.trim());
  return {
    question: generated.question,
    aiPick:   generated.aiPick,
    aiReason: generated.aiReason,
  };
}

// ─── Main handler ──────────────────────────────────────────────────────────────
module.exports = async function (context, req) {
  const method = req.method?.toUpperCase();

  try {
    const container = getContainerClient();

    // ── GET ───────────────────────────────────────────────────────────────────
    if (method === 'GET') {
      if (!container) {
        context.res = { status: 503, body: { error: 'Storage unavailable' } };
        return;
      }

      const language = (req.query.lang === 'en') ? 'en' : 'ar';
      const blobName = `current-${language}.json`;

      let data = null;
      try { data = await readBlob(container, blobName); } catch { /* not found */ }

      // Regenerate if missing or from a previous day
      if (!data || data.period !== todayKey()) {
        const generated = await generateQuestion(language);
        data = {
          period:    todayKey(),
          question:  generated.question,
          aiPick:    generated.aiPick,
          aiReason:  generated.aiReason,
          yesCount:  0,
          noCount:   0,
          votes:     {},        // anonId → 'yes'|'no'
          expiresAt: tomorrowMidnightUTC(),
        };
        await writeBlob(container, blobName, data);
      }

      // Omit voter map from public response
      const { votes, ...publicData } = data;
      context.res = {
        status:  200,
        headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' },
        body:    publicData,
      };
      return;
    }

    // ── POST (vote) ───────────────────────────────────────────────────────────
    if (method === 'POST') {
      if (!container) {
        context.res = { status: 503, body: { error: 'Storage unavailable' } };
        return;
      }

      const { anonId, vote, lang: bodyLang = 'ar' } = req.body || {};

      // Basic input validation
      if (!anonId || typeof anonId !== 'string' || anonId.length > 64) {
        context.res = { status: 400, body: { error: 'Invalid anonId' } };
        return;
      }
      if (!['yes', 'no'].includes(vote)) {
        context.res = { status: 400, body: { error: 'vote must be "yes" or "no"' } };
        return;
      }

      const language = (bodyLang === 'en') ? 'en' : 'ar';
      const blobName = `current-${language}.json`;

      let data = null;
      try { data = await readBlob(container, blobName); } catch { /* not found */ }

      if (!data || data.period !== todayKey()) {
        context.res = { status: 404, body: { error: 'No active question for today' } };
        return;
      }

      // Idempotent: return current counts if already voted
      if (data.votes[anonId]) {
        const { votes, ...publicData } = data;
        context.res = { status: 200, headers: { 'Content-Type': 'application/json' }, body: publicData };
        return;
      }

      data.votes[anonId] = vote;
      data[vote === 'yes' ? 'yesCount' : 'noCount']++;

      await writeBlob(container, blobName, data);

      const { votes, ...publicData } = data;
      context.res = {
        status:  200,
        headers: { 'Content-Type': 'application/json' },
        body:    publicData,
      };
      return;
    }

    context.res = { status: 405, body: { error: 'Method not allowed' } };
  } catch (err) {
    context.log.error('predictions API error:', err);
    context.res = { status: 500, body: { error: 'Internal server error' } };
  }
};
